"""Whole lib/list_sort.c: stable merge and binary pending-run schedule."""
def register(topic, q, detail):
    def lesson(title, symbol, why, principle, use, reading, qa, cards):
        topic(title, '라이브러리·알고리즘', 'lib/list_sort.c', symbol,
              why, principle, use, reading, *(q(*x) for x in qa),
              details=[detail(*x) for x in cards])

    lesson('연결 리스트 정렬·두 정렬된 열을 안정적으로 합치기', 'merge',
        '배열 복사 없이 노드의 next 연결만 바꾸어 두 정렬된 열을 합치는 방법을 배웁니다.',
        'a와 b는 각각 NULL로 끝나는 정렬된 노드 열입니다. 비교 결과가 0 이하이면 a를 먼저 연결하고, 양수이면 b를 먼저 연결합니다. tail은 마지막 노드 자체가 아니라 다음 포인터를 써야 할 위치를 가리킵니다. 한 열이 끝나면 다른 열의 나머지를 그대로 연결합니다. 같은 키에서 더 오래된 a를 먼저 선택하므로 입력 순서가 유지됩니다.',
        '이 내부 함수의 두 입력은 비어 있지 않아야 합니다. 중간 결과에는 sentinel head가 없고 prev 연결도 유지하지 않습니다. 공개 list_sort만 정상 원형 양방향 리스트를 입력받고 결과를 그 형태로 복원합니다.',
        'struct list_head **tail과 tail=&a->next가 각각 가리키는 대상을 그려 보세요.',
        [('동일 키에서 먼저 a를 선택하는 이유는?', '같은 키의 기존 입력 순서를 유지하기 위해서다', 'a의 주소가 항상 더 작기 때문이다', '호출자는 오래된 열을 a에 놓습니다. 동률에서 a를 먼저 연결하면 두 열 안의 순서와 열 사이의 원래 순서가 함께 보존됩니다.'),
         ('중간 merge 결과의 prev 포인터로 일반 리스트 순회를 해도 되는가?', '안 되며 마지막 복원이 끝나야 한다', '정렬 중에도 항상 양방향 연결이 완성되어 있다', 'merge는 next 연결만 유지합니다. prev는 중간 관리용으로 쓰이거나 이전 값을 가지므로 일반 양방향 순회 계약이 없습니다.')],
        [('포인터의 포인터', '*tail=a는 다음 연결을 저장할 자리에 a를 씁니다. 첫 자리인 head에도 이후 노드의 next에도 같은 대입 방식이 적용됩니다.'),
         ('노드 보존', '원소를 새로 할당하거나 내용물을 복사하지 않습니다. 노드의 주소와 내용은 유지되고 연결 순서가 바뀝니다.')])

    lesson('연결 리스트 정렬·최종 병합과 원형 연결 복원', 'merge_final',
        '마지막 병합에서 양방향 연결과 원형 head를 동시에 복원하는 원리를 배웁니다.',
        'tail은 처음 head입니다. 선택한 노드를 tail->next에 연결하고 그 노드의 prev를 tail로 설정합니다. 한 열이 끝나면 남은 열을 이어 붙이면서 prev를 계속 복원합니다. 마지막 노드의 next를 head에 연결하고 head->prev를 마지막 노드로 설정하면 원형 양방향 구조가 완성됩니다.',
        '공개 함수가 반환한 뒤 next와 prev를 각각 순회해 서로 역순인지 확인합니다. 중간 병합에서 매번 prev를 고치거나 마지막에 별도 복원 순회를 하지 않고 최종 병합에 복원 작업을 결합한 설계입니다.',
        'tail->next, a->prev, head->prev의 갱신 순서를 읽으세요.',
        [('마지막 노드의 next는 어디를 가리켜야 하는가?', 'sentinel head를 가리킨다', '반드시 NULL을 가리킨다', '중간 열은 NULL로 끝나지만 공개 결과는 원형 리스트입니다. 마지막 next와 head의 prev를 연결해야 양방향 원형 계약이 복원됩니다.'),
         ('최종 병합에서 prev를 함께 고치는 목적은?', '병합과 복원을 같은 흐름으로 수행하기 위해서다', '원소 내용을 비교하기 전에 삭제하기 위해서다', '선택한 노드를 연결할 때 이전 노드를 이미 알고 있습니다. 그 자리에서 prev를 복원하면 별도의 전체 복원 단계가 필요하지 않습니다.')],
        [('u8 계수기', '나머지 열 순회 중 count는 8비트 부호 없는 값입니다. 256번 증가하면 0이 되어 비교가 필요 없어도 cmp(priv,b,b)를 호출합니다.'),
         ('자기 비교와 양보', '긴 순회에서도 비교 콜백이 주기적으로 실행되므로 콜백이 허용되는 문맥에서 cond_resched 등을 호출할 기회를 가질 수 있습니다. list_sort 자체가 매번 스케줄링하거나 양보를 보장하는 것은 아닙니다.')])

    lesson('리스트 비교 계약·부울 결과와 자기 비교', 'list_sort',
        '안정 정렬이 허용하는 비교 함수 형식과 실제 호출 조건을 배웁니다.',
        'cmp(priv,a,b)는 a가 b 뒤에 와야 하면 양수를 반환하고, 앞에 와도 되거나 기존 순서를 유지해야 하면 0 이하를 반환합니다. 일반적인 음수·0·양수 비교와 a>b의 부울 0·1 비교가 모두 가능합니다. 서로 다른 원소를 비교할 때 a는 입력에서 더 먼저 온 원소입니다. 최종 복원 중에는 동일 노드 b,b를 비교하는 호출도 발생합니다.',
        '콜백은 같은 노드 비교를 안전하게 처리하고 모든 호출에서 같은 정렬 기준을 유지해야 합니다. 여러 필드라면 상위 필드가 다를 때 먼저 판단하고 같으면 다음 필드를 비교합니다. 반환값을 정수 뺄셈으로 만들 때 발생할 수 있는 overflow도 피합니다.',
        '함수 앞 비교 계약과 list_sort.h의 priv-first 콜백 선언을 연결하세요.',
        [('부울 비교가 반환해야 하는 참 조건은?', 'a가 b보다 뒤에 정렬되어야 한다는 조건이다', 'a가 b보다 앞에 오거나 같다는 조건이다', '양수는 b를 먼저 고르는 뜻입니다. a>b이면 1을 반환하면 오름차순 정렬 계약과 맞습니다.'),
         ('콜백에서 a와 b가 항상 서로 다른 노드라고 가정해도 되는가?', '안 되며 같은 노드 호출도 처리해야 한다', '가능하며 원본은 자기 비교를 하지 않는다', 'merge_final의 긴 나머지 연결은 주기적으로 cmp(priv,b,b)를 호출합니다. 내용 비교만 필요한 호출이라고 제한하면 실제 계약을 놓칩니다.')],
        [('사전식 비교', 'high가 다르면 high로 결정하고, 같으면 middle, 그것도 같으면 low를 비교합니다. 앞 필드에서 결과가 정해진 뒤 뒤 필드로 덮어쓰지 않습니다.'),
         ('호출 문맥', '비교에서 스케줄링을 고려한다면 호출 문맥과 잠금 조건이 허용해야 합니다. 정렬 도중에는 리스트의 일반 연결이 깨져 있으므로 다른 독자나 콜백이 그 리스트를 일반 순회하지 못하게 보호합니다.')])

    lesson('리스트 정렬·노드 필드를 재사용한 pending 열', 'list_sort',
        '추가 배열을 만들지 않고 정렬 중인 부분 열들을 노드 필드로 관리하는 방법을 배웁니다.',
        '0개 또는 1개는 head->next==head->prev 검사로 바로 반환합니다. 나머지는 마지막 next를 NULL로 바꾸어 입력을 단방향 열로 만듭니다. pending은 정렬된 부분 열들의 시작 노드를 prev로 연결한 관리 열입니다. 각 부분 열의 크기는 2의 거듭제곱이고 같은 크기는 최대 두 개이며 작은 것과 최신 것이 앞에 있습니다. 입력 노드를 한 개씩 크기 1의 새 열로 넣습니다.',
        'prev가 정렬 전의 이전 원소를 계속 가리킨다고 생각하지 않습니다. 입력 전체의 노드 수와 주소가 보존되는지, 반환 후 head를 포함한 원형 연결이 복원되는지 확인합니다. 정렬 중 연결을 볼 수 있는 다른 접근은 호출자가 제어해야 합니다.',
        'list->prev=pending과 pending->next=NULL이 서로 다른 역할을 하는지 읽으세요.',
        [('pending의 prev 연결은 정렬 중 무엇을 나타내는가?', '병합을 기다리는 다른 부분 열의 시작 노드다', '항상 최종 정렬 결과에서 바로 이전 원소다', '부분 열 내부는 next로 순회하고 시작 노드의 prev는 관리 열에 사용합니다. 일반 양방향 prev와 의미가 다릅니다.'),
         ('공개 함수에 빈 원형 리스트를 주면 어떻게 되는가?', '연결을 바꾸지 않고 반환한다', 'head를 일반 데이터 노드로 비교한다', '빈 경우 head->next와 head->prev가 모두 head입니다. 0·1개 조기 반환 검사에서 끝나므로 비교할 데이터가 없습니다.')],
        [('head의 역할', 'sentinel head는 원소 비교에 포함하지 않습니다. 중간 단방향 열에서 제외했다가 최종 병합으로 원형 구조에 다시 연결합니다.'),
         ('수명과 소유권', '정렬은 노드 할당·해제와 수명 관리를 하지 않습니다. 모든 입력 노드는 호출이 끝날 때까지 유효해야 합니다.')])

    lesson('리스트 병합 일정·이진 계수와 여섯 상태', 'list_sort',
        '부분 열을 너무 일찍 합치지 않으면서 최종 병합의 균형을 지키는 이진 계수 원리를 배웁니다.',
        'count는 이미 pending에 들어간 원소 수입니다. 낮은 연속 1비트를 따라 prev 관리 열을 이동해 가장 낮은 0비트의 위치를 찾습니다. 남은 bits가 0이면 해당 크기의 첫 도달이므로 병합하지 않습니다. 0이 아니면 그 위치의 같은 크기 두 열을 합칩니다. 2^k 뒤따르는 원소가 확보된 시점에 두 크기 2^k 열을 합쳐 최종 병합의 불균형을 최대 2:1로 제한합니다.',
        '원본 주석의 여섯 상태는 bit k, 바로 아래 비트, 더 높은 비트의 유무를 함께 구분합니다. 상태 2→3, 4→5에서 해당 크기 열이 늘고 5→2에서 두 열이 병합됩니다. 단순히 count의 켜진 비트마다 열 한 개가 있다고 해석하지 말고 최대 두 개 조건을 함께 추적합니다.',
        'count 0..7에서 실제 병합을 하는 시점과 새 크기 1 열을 추가하는 시점을 따로 적으세요.',
        [('count=3에서 낮은 연속 1비트를 모두 지나 bits=0이면?', '그 회차에는 기존 열을 병합하지 않는다', 'NULL 관리 포인터를 무조건 역참조한다', '병합 본문은 likely(bits) 조건으로 보호됩니다. 첫 도달에서는 두 해당 크기 열이 아직 준비되지 않았으므로 병합을 생략합니다.'),
         ('같은 크기의 pending 열이 가질 수 있는 최대 개수는?', '두 개다', '입력 길이만큼 제한 없이 늘어난다', '원본의 병합 일정은 같은 크기의 세 번째 열을 만들기 전에 기존 두 열을 더 큰 열로 합칩니다. 이 조건이 pending 관리와 균형 분석에 사용됩니다.')],
        [('여섯 상태 표', '00x와 01x는 해당 크기 열이 0개입니다. x10x도 0개, x11x는 1개, 높은 비트가 있는 y00x는 1개, y01x는 2개입니다. x는 임의 낮은 비트이고 y는 0이 아닌 높은 비트입니다. k=0에서는 아래 비트를 항상 1로 간주합니다.'),
         ('캐시와 비교 수', '주석은 3*2^k 원소가 캐시에 들어가는 조건과 완전 즉시 병합 방식보다 줄어드는 비교 수를 설명합니다. 이는 설계 분석이며 실제 특정 CPU의 캐시 크기나 실행 시간 측정 결과와 구분합니다.')])

    lesson('리스트 정렬·작은 열부터 최종 병합하기', 'list_sort',
        '입력을 모두 처리한 뒤 남은 열을 합치고 안정 정렬 결과를 완성하는 방법을 배웁니다.',
        '입력 처리가 끝나면 pending의 가장 작은 최신 열에서 시작합니다. 관리 prev를 따라 더 큰 오래된 열과 merge(pending,list)를 반복합니다. 오래된 열을 a에 놓으므로 같은 키의 기존 순서가 보존됩니다. 마지막 두 열은 merge_final로 합쳐 양방향 원형 연결을 복원합니다. 원본 분석에서 크기 2^k 열과 합치는 나머지 길이는 2^(k-1)부터 2^(k+1)-1 범위입니다.',
        '배열 sort와 달리 안정성이 필요한 연결 리스트에 적합합니다. 시간은 병합 정렬의 O(n log n)이고 별도 원소 배열이나 재귀 스택을 만들지 않습니다. 기존 next·prev 필드를 중간 구조에 재사용하므로 다른 순회와 동시에 실행하지 않습니다.',
        'next=pending->prev를 먼저 보관하는 이유와 마지막 merge_final 호출을 읽으세요.',
        [('최종 merge 호출에서 오래된 pending 열을 첫 입력에 넣는 이유는?', '동일 키에서 먼저 선택하여 원래 순서를 보존하기 위해서다', '오래된 원소를 모두 삭제하기 위해서다', 'merge는 동률에서 첫 입력 a를 선택합니다. 열 내부 순서만 아니라 서로 다른 열의 입력 시점도 보존해야 안정 정렬이 완성됩니다.'),
         ('이 구현에서 노드 주소는 정렬 후 바뀌는가?', '주소는 유지되고 연결 순서가 바뀐다', '모든 노드를 새 주소로 재할당한다', '원본은 연결 포인터를 재구성합니다. 새 노드 할당이나 내용 복사 없이 기존 노드를 정렬된 순서로 연결합니다.')],
        [('공개 헤더', 'include/linux/list_sort.h는 list_head를 전방 선언하고 priv가 첫 인자인 list_cmp_func_t와 list_sort 선언을 제공합니다. nonnull 속성은 head와 비교 함수 등의 필수 인자를 컴파일러에 알리며 런타임 NULL 검사로 대체되지 않습니다.'),
         ('비교 대상 범위', '실행 검증에서는 중복 키의 입력 번호 순서, 모든 노드의 1회 등장, next/prev 상호 연결과 head 원형 복원을 함께 확인합니다. 값만 오름차순인지 확인하면 안정성이나 노드 누락을 놓칠 수 있습니다.')])
